package com.studentrental.controller;
import com.studentrental.model.*;import com.studentrental.repo.*;import com.studentrental.service.CurrentUser;
import org.springframework.http.*;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @RequestMapping("/api/items")
public class ItemController{
 final ItemRepository items;final UserRepository users;final CurrentUser current;
 public ItemController(ItemRepository i,UserRepository u,CurrentUser c){items=i;users=u;current=c;}
 Map<String,Object> dto(RentalItem x){Map<String,Object> m=new LinkedHashMap<>();m.put("id",x.getId());m.put("title",x.getTitle());m.put("description",x.getDescription());m.put("category",x.getCategory());m.put("pricePerDay",x.getPricePerDay());m.put("deposit",x.getDeposit());m.put("conditionLabel",x.getConditionLabel()==null?"Good":x.getConditionLabel());m.put("imageUrl",x.getImageUrl()==null?"":x.getImageUrl());m.put("location",x.getLocation()==null?"":x.getLocation());m.put("available",x.isAvailable());m.put("ownerId",x.getOwner().getId());m.put("ownerName",x.getOwner().getName());m.put("ownerVerified",x.getOwner().isVerified());m.put("createdAt",x.getCreatedAt());return m;}
 @GetMapping List<Map<String,Object>> all(@RequestParam(required=false) String q,@RequestParam(required=false) String category,@RequestParam(required=false) String location){
  return items.findByAvailableTrueOrderByCreatedAtDesc().stream().filter(x->q==null||q.isBlank()||(x.getTitle()+" "+x.getDescription()+" "+x.getCategory()).toLowerCase().contains(q.toLowerCase())).filter(x->category==null||category.isBlank()||category.equalsIgnoreCase(x.getCategory())).filter(x->location==null||location.isBlank()||(x.getLocation()!=null&&x.getLocation().toLowerCase().contains(location.toLowerCase()))).map(this::dto).toList();
 }
 @GetMapping("/mine") List<Map<String,Object>> mine(){return items.findByOwnerIdOrderByCreatedAtDesc(current.get().getId()).stream().map(this::dto).toList();}
 @PostMapping ResponseEntity<?> create(@RequestBody Map<String,Object> b){try{RentalItem x=new RentalItem();apply(x,b);x.setOwner(current.get());return ResponseEntity.ok(dto(items.save(x)));}catch(Exception e){return ResponseEntity.badRequest().body(Map.of("message","Please provide title, description, category and a valid price"));}}
 @PutMapping("/{id}") ResponseEntity<?> update(@PathVariable Long id,@RequestBody Map<String,Object>b){RentalItem x=items.findById(id).orElse(null);if(x==null)return ResponseEntity.notFound().build();if(!x.getOwner().getId().equals(current.get().getId())&&!current.get().getRole().equals(Role.ADMIN))return ResponseEntity.status(403).build();apply(x,b);return ResponseEntity.ok(dto(items.save(x)));}
 @DeleteMapping("/{id}") ResponseEntity<?> delete(@PathVariable Long id){RentalItem x=items.findById(id).orElse(null);if(x==null)return ResponseEntity.notFound().build();if(!x.getOwner().getId().equals(current.get().getId())&&!current.get().getRole().equals(Role.ADMIN))return ResponseEntity.status(403).build();items.delete(x);return ResponseEntity.noContent().build();}
 void apply(RentalItem x,Map<String,Object>b){x.setTitle(str(b,"title"));x.setDescription(str(b,"description"));x.setCategory(str(b,"category"));x.setPricePerDay(num(b,"pricePerDay"));x.setDeposit(num(b,"deposit"));x.setConditionLabel(b.getOrDefault("conditionLabel","Good").toString());x.setImageUrl(b.getOrDefault("imageUrl","").toString());x.setLocation(b.getOrDefault("location","").toString());x.setAvailable(!b.containsKey("available")||Boolean.parseBoolean(b.get("available").toString()));if(x.getTitle().isBlank()||x.getDescription().isBlank()||x.getCategory().isBlank()||x.getPricePerDay()<=0)throw new IllegalArgumentException();}
 String str(Map<String,Object>b,String k){return Objects.toString(b.get(k),"").trim();}double num(Map<String,Object>b,String k){return Double.parseDouble(Objects.toString(b.getOrDefault(k,0),"0"));}
}
